let cd = AudioCd::new(drive_path)?.lock();
let track = cd.rip(1)?;
let flac_sink = track.to_flac();

// Get the FLAC data as bytes
let flac_bytes = flac_sink.into_inner();
# Ok::<(), io::Error>(())
```

